UPDATE public.product_images pi SET format = CASE WHEN lower(a.filename) ~ '\.(jpe?g)$' THEN 'jpeg' WHEN lower(a.filename) ~ '\.png$' THEN 'png' WHEN lower(a.filename) ~ '\.webp$' THEN 'webp' WHEN lower(a.filename) ~ '\.gif$' THEN 'gif' WHEN lower(a.filename) ~ '\.svg$' THEN 'svg' ELSE 'jpeg' END, last_modified_source='claude', updated_at=now() FROM public._cf_images_audit a WHERE pi.cloudflare_image_id=a.cf_id AND pi.format IS NULL AND pi.deleted_at IS NULL; UPDATE public.product_images SET format='jpeg', last_modified_source='claude', updated_at=now() WHERE format IS NULL AND deleted_at IS NULL;;
